mapper.select:
select stat_month as statMonth, algorithm_id as algorithmId, total_cmds as totalCmds, qualified_fast as qualifiedFast, penalized_fast as penalizedFast, exempted_fast as exemptedFast, invalid_fast as invalidFast, qualified_econ as qualifiedEcon, penalized_econ as penalizedEcon, exempted_econ as exemptedEcon, invalid_econ as invalidEcon, undecodable_count as undecodableCount, pended_count as pendedCount, excluded_count as excludedCount, completeness_sum as completenessSum from vqms_regulation_monthly
stat_month = #{statMonth}
order by stat_month desc

select stat_month as statMonth, in_service_min as inServiceMin, exit_grid_min as exitGridMin, exit_nongrid_min as exitNonGridMin, offline_min as offlineMin, rated_capacity_kw as ratedCapacityKw, rate_pct as ratePct, shortfall_pct as shortfallPct, penalty_score as penaltyScore from vqms_runtime_monthly
stat_month = #{statMonth}
order by stat_month desc
